qualified_questions.sparql_query:
PREFIX BO: <http://example.org/ontology/BO#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?areaNetwork ?netTechnologyProfile
WHERE {
  ?areaNetwork rdf:type BO:AreaNetwork ;
               BO:netTechnologyProfile ?netTechnologyProfile .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/ontology/BO#>

SELECT ?areaNetwork
WHERE {
  ?areaNetwork rdf:type BO:AreaNetwork ;
               BO:netTechnologyPhysicalStandard ?physicalStandard ;
               BO:oneM2MMethod ?oneM2MMethod .
  FILTER(?physicalStandard = "specific_physical_standard" && ?oneM2MMethod = "given_oneM2M_method")
}

PREFIX BO: <http://example.org/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT (COUNT(?areaNetwork) AS ?count)
WHERE {
  ?areaNetwork rdf:type BO:AreaNetwork ;
               BO:netTechnologyProfile ?profile ;
               BO:netTechnologyCommunicationProtocol ?protocol .
  FILTER (?profile = "specific_network_technology_profile" && ?protocol = "particular_communication_protocol")
}

PREFIX BO: <http://example.org/ontology/BO#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?netTechnologyProfile
WHERE {
  ?areaNetwork rdf:type BO:AreaNetwork ;
               BO:netTechnologyCommunicationProtocol ?communicationProtocol ;
               BO:netTechnologyProfile ?netTechnologyProfile .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX BO: <http://example.org/BO#>

SELECT ?variable
WHERE {
  ?variable rdf:type BO:StructuredTypeVariable ;
            BO:hasSubStructure ?substructure .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/BO#>

SELECT ?relationship
WHERE {
  BO:OperationOutput rdfs:subClassOf* ?relationship .
  ?relationship rdf:type owl:Class ;
                rdfs:subClassOf* BO:Variable .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX BO: <http://example.org/BO#>

SELECT ?variable
WHERE {
  ?variable a BO:StructuredTypeVariable ;
            BO:hasSubStructure ?substructure .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX BO: <http://example.org/BO#>

SELECT ?variable
WHERE {
  ?variable a BO:Variable .
  {
    ?operation BO:hasInput ?variable .
  }
  UNION
  {
    ?operation BO:hasOutput ?variable .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX BO: <http://example.org/ontology/BO#>

SELECT ?definition
WHERE {
  BO:Service rdfs:subClassOf ?superClass .
  OPTIONAL { ?superClass rdfs:comment ?definition }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/ontology/BO#>

SELECT ?device ?function
WHERE {
  ?device rdf:type BO:Device ;
          BO:hasFunction ?function .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX BO: <http://example.org/ontology/BO#>

SELECT ?thing ?characteristic
WHERE {
  ?thing rdf:type BO:Thing .
  OPTIONAL {
    ?thing BO:hasThingProperty ?property .
    ?property rdf:type BO:ThingProperty .
    BIND(?property AS ?characteristic)
  }
  OPTIONAL {
    ?thing BO:hasFunction ?function .
    ?function rdf:type BO:Function .
    BIND(?function AS ?characteristic)
  }
  OPTIONAL {
    ?thing BO:hasOperation ?operation .
    ?operation rdf:type BO:Operation .
    BIND(?operation AS ?characteristic)
  }
  OPTIONAL {
    ?thing BO:hasCommand ?command .
    ?command rdf:type BO:Command .
    BIND(?command AS ?characteristic)
  }
  OPTIONAL {
    ?thing BO:hasMetaData ?metaData .
    ?metaData rdf:type BO:MetaData .
    BIND(?metaData AS ?characteristic)
  }
  OPTIONAL {
    ?thing BO:hasThingRelation ?relatedThing .
    ?relatedThing rdf:type BO:Thing .
    BIND(?relatedThing AS ?characteristic)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/BO#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?simpleTypeVariable ?minInclusive ?maxInclusive ?minExclusive ?maxExclusive ?minLength ?maxLength ?pattern
WHERE {
  ?simpleTypeVariable rdf:type BO:SimpleTypeVariable .
  OPTIONAL { ?simpleTypeVariable BO:hasDataRestriction_minInclusive ?minInclusive . }
  OPTIONAL { ?simpleTypeVariable BO:hasDataRestriction_maxInclusive ?maxInclusive . }
  OPTIONAL { ?simpleTypeVariable BO:hasDataRestriction_minExclusive ?minExclusive . }
  OPTIONAL { ?simpleTypeVariable BO:hasDataRestriction_maxExclusive ?maxExclusive . }
  OPTIONAL { ?simpleTypeVariable BO:hasDataRestriction_minLength ?minLength . }
  OPTIONAL { ?simpleTypeVariable BO:hasDataRestriction_maxLength ?maxLength . }
  OPTIONAL { ?simpleTypeVariable BO:hasDataRestriction_pattern ?pattern . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/ontology/BO#>

SELECT ?thing ?annotation
WHERE {
  ?thing rdf:type BO:Thing ;
         BO:hasThingAnnotation ?annotation .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX BO: <http://example.org/BO#>

SELECT ?value
WHERE {
  ?variable rdf:type BO:SimpleTypeVariable ;
            BO:hasValue ?value .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?versionIRI
WHERE {
  <https://git.onem2m.org/MAS/BaseOntology/raw/master/base_ontology.owl> owl:versionIRI ?versionIRI .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?currentVersion ?previousVersion
WHERE {
  <https://git.onem2m.org/MAS/BaseOntology/raw/master/base_ontology.owl> rdf:type owl:Ontology ;
  owl:versionIRI ?currentVersion .
  FILTER(?previousVersion = <https://git.onem2m.org/MAS/BaseOntology/raw/3_6_0/base_ontology.owl>)
}
